def verify(data):
    """Confirm every stored URL actually resolves. Migration 0005 exists
    because 22 entries shipped with dead links."""
    bad = []
    urls = sorted({p["url"] for papers in data.values() for p in papers})
    for i, url in enumerate(urls, 1):
